service.method:

INSERT
  INTO SBUPR
     ( HOUSE_CODE
     , BIZ_CODE
     , BIZ_CATEGORY
     , BIZ_TYPE
     , ADD_DATE
     , ADD_TIME
     , ADD_USER_ID
     , CHANGE_DATE
     , CHANGE_TIME
     , CHANGE_USER_ID
     , DEL_FLAG
     , SELLER_NAME_LOC
     , IRS_NO
     , ZIP_CODE
     , ADDRESS_LOC
     , PHONE_NO
     , EMAIL
     , CEO_NAME_LOC
     , FOUNDATION_DATE
     , IF_FLAG
     )
VALUES
     ( ${session.HOUSE_CODE}
     , ${BIZ_CODE}
     , ${BIZ_CATEGORY}
     , ${BIZ_TYPE}
     , ${current.DATE}
     , ${current.TIME}
     , ${session.ID}
     , ${current.DATE}
     , ${current.TIME}
     , ${session.ID}
     , 'N'
     , ${SELLER_NAME_LOC}
     , ${IRS_NO}
     , ${ZIP_CODE}
     , ${ADDRESS_LOC}
     , ${PHONE_NO}
     , ${EMAIL}
     , ${CEO_NAME_LOC}
     , ${FOUNDATION_DATE}
     , ${IF_FLAG}
     )


UPDATE SBUPR
   SET CHANGE_DATE          = ${current.DATE}
     , CHANGE_TIME          = ${current.TIME}
     , CHANGE_USER_ID       = ${session.ID}
     , SELLER_NAME_LOC      = #DB_OWNER#nvl(${SELLER_NAME_LOC}      , SELLER_NAME_LOC)
     , IRS_NO               = #DB_OWNER#nvl(${IRS_NO}               , IRS_NO)
     , ZIP_CODE             = #DB_OWNER#nvl(${ZIP_CODE}             , ZIP_CODE)
     , ADDRESS_LOC          = #DB_OWNER#nvl(${ADDRESS_LOC}          , ADDRESS_LOC)
     , PHONE_NO             = #DB_OWNER#nvl(${PHONE_NO}             , PHONE_NO)
     , EMAIL                = #DB_OWNER#nvl(${EMAIL}                , EMAIL)
     , CEO_NAME_LOC         = #DB_OWNER#nvl(${CEO_NAME_LOC}         , CEO_NAME_LOC)
     , FOUNDATION_DATE      = #DB_OWNER#nvl(${FOUNDATION_DATE}      , FOUNDATION_DATE)
 WHERE HOUSE_CODE           = ${session.HOUSE_CODE}
   AND BIZ_CODE             = ${BIZ_CODE}
   AND BIZ_CATEGORY         = ${BIZ_CATEGORY}
   AND BIZ_TYPE             = ${BIZ_TYPE}


UPDATE SBUPR
   SET CHANGE_DATE      = ${current.DATE}
     , CHANGE_TIME      = ${current.TIME}
     , CHANGE_USER_ID   = ${session.ID}
     , DEL_FLAG         = 'Y'
 WHERE HOUSE_CODE       = ${session.HOUSE_CODE}
   AND BIZ_CODE         = ${BIZ_CODE}
   AND BIZ_CATEGORY     = ${BIZ_CATEGORY}
   AND BIZ_TYPE         = ${BIZ_TYPE}


INSERT
  INTO SBUPI
     ( HOUSE_CODE
     , BIZ_CODE
     , SEQ
     , USER_ID
     , ADD_DATE
     , ADD_TIME
     , ADD_USER_ID
     , CHANGE_DATE
     , CHANGE_TIME
     , CHANGE_USER_ID
     , DEL_FLAG
     , USER_NAME
     , EMAIL
     , PHONE_NO
     , IF_FLAG
     )
VALUES
     ( ${session.HOUSE_CODE}
     , ${BIZ_CODE}
     , CASE WHEN ( #DB_OWNER#nvl(${SEQ}, '__SEQ_IS_EMPTY__') ) = '__SEQ_IS_EMPTY__'
            THEN TO_CHAR((
                SELECT TO_NUMBER(#DB_OWNER#nvl(MAX(SEQ), '0')) + 1
                  FROM SBUPI
                 WHERE HOUSE_CODE = ${session.HOUSE_CODE}
                   AND BIZ_CODE   = ${BIZ_CODE}
            ))
            ELSE '0'
            END
     , ${USER_ID}
     , ${current.DATE}
     , ${current.TIME}
     , ${session.ID}
     , ${current.DATE}
     , ${current.TIME}
     , ${session.ID}
     , 'N'
     , ${USER_NAME}
     , ${EMAIL}
     , ${PHONE_NO}
     , ${IF_FLAG}
     )


UPDATE SBUPI
   SET CHANGE_DATE          = ${current.DATE}
     , CHANGE_TIME          = ${current.TIME}
     , CHANGE_USER_ID       = ${session.ID}
     , USER_NAME            = #DB_OWNER#nvl(${USER_NAME}    , USER_NAME)
     , EMAIL                = #DB_OWNER#nvl(${EMAIL}        , EMAIL)
     , PHONE_NO             = #DB_OWNER#nvl(${PHONE_NO}     , PHONE_NO)
 WHERE HOUSE_CODE           = ${session.HOUSE_CODE}
   AND BIZ_CODE             = ${BIZ_CODE}
   AND USER_ID              = ${USER_ID}


UPDATE SBUPI
   SET CHANGE_DATE      = ${current.DATE}
     , CHANGE_TIME      = ${current.TIME}
     , CHANGE_USER_ID   = ${session.ID}
     , DEL_FLAG         = 'Y'
 WHERE HOUSE_CODE       = ${session.HOUSE_CODE}
   AND BIZ_CODE         = ${BIZ_CODE}
   AND USER_ID          = ${USER_ID}


INSERT
  INTO SUSMT
     ( HOUSE_CODE
     , USER_ID
     , ADD_DATE
     , ADD_TIME
     , ADD_USER_ID
     , CHANGE_DATE
     , CHANGE_TIME
     , CHANGE_USER_ID
     , COMPANY_CODE
     , USER_NAME_LOC
     , USER_NAME_ENG
     , PASSWORD
     , LANGUAGE
     , TIME_ZONE
     , EMAIL
     , COUNTRY
     , SIGN_STATUS
     , WORK_TYPE
     , MENU_PROFILE_CODE
     , USER_TYPE
     , PASS_CHECK_CNT
     , PW_RESET_FLAG
     , DEL_FLAG
     , DATE_FORMAT
     , PHONE
     )
VALUES
     ( ${session.HOUSE_CODE}
     , UPPER(${USER_ID})
     , ${current.DATE}
     , ${current.TIME}
     , ${session.ID}
     , ${current.DATE}
     , ${current.TIME}
     , ${session.ID}
     , ${BIZ_CODE}
     , ${USER_NAME}
     , ${USER_NAME}
     , ${PASSWORD}
     , ${LANGUAGE}
     , ${TIME_ZONE}
     , ${EMAIL}
     , ${COUNTRY}
     , ${SIGN_STATUS}
     , ${WORK_TYPE}
     , ${MENU_PROFILE_CODE}
     , ${USER_TYPE}
     , 0
     , 'N'
     , 'N'
     , ${DATE_FORMAT}
     , ${PHONE}
     )


UPDATE SUSMT
   SET CHANGE_DATE      = ${current.DATE}
     , CHANGE_TIME      = ${current.TIME}
     , CHANGE_USER_ID   = ${session.ID}
     , DEL_FLAG         = 'Y'
 WHERE HOUSE_CODE       = ${session.HOUSE_CODE}
   AND USER_ID          = ${USER_ID}
